def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    highest_prev = 0.0
    cindy_prev = None
    pressure_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            if bid > highest_prev:
                highest_prev = bid
            if bid >= 80:
                pressure_count += 1
        if prev and opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if bid is not None and bid >= 90:
                cindy_prev = float(bid)

    units = supply / WATER_REQ
    scarce = units < 1.6
    comfortable = units >= 1.9
    critical = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    if critical:
        target = max(95.0, highest_prev + 2.0)
        if scarce:
            target = max(target, 108.0)
        return float(min(budget, target))

    if scarce:
        if cindy_prev is not None:
            target = cindy_prev + 1.5
        else:
            target = max(88.0, highest_prev + 1.5)
        if fragile:
            target += 6.0
        return float(min(budget, target))

    if comfortable and hp > 5 and no_water_days == 0:
        low = 12.0
        if highest_prev <= 20:
            low = 8.0
        return float(min(budget, low))

    if highest_prev >= 110:
        target = 26.0 if hp > 5 else 72.0
    elif highest_prev >= 90:
        target = 34.0 if hp > 5 else 84.0
    elif highest_prev >= 50:
        target = highest_prev + 1.5 if fragile else 28.0
    else:
        target = 22.0 if hp > 5 else 48.0

    if day >= 8 and hp <= 5:
        target = max(target, 78.0)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate trace only
    prev_bids = []
    prev_by_id = {}
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_f = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_f)
            prev_by_id[opp_id] = bid_f

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If Cindy was aggressive yesterday, assume she will pressure again.
    cindy_prev = prev_by_id.get('Cindy', None)
    cindy_pressure = float(cindy_prev) if cindy_prev is not None else 0.0

    # Determine how many water units are feasible/needed today.
    # Bids are in budget units, but we use supply to decide how hard to compete.
    # Expected water per unit is 1, so 1 unit corresponds to meeting WATER_REQ.
    # We'll translate supply urgency into a bid aggressiveness level.
    supply_ratio = 0.0
    if MAX_SUPPLY > 0:
        supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid target: aim to secure water when supply is tighter and when my HP/no-water is risky.
    # If my HP is low or I've already had no water days, bid harder.
    hp_risk = 0.0
    if my_hp <= 1:
        hp_risk = 1.0
    elif my_hp <= 3:
        hp_risk = 0.7
    elif my_hp <= 5:
        hp_risk = 0.4
    else:
        hp_risk = 0.2

    no_water_risk = 0.0
    if my_no_water_days >= 2:
        no_water_risk = 1.0
    elif my_no_water_days == 1:
        no_water_risk = 0.5
    else:
        no_water_risk = 0.1

    # Aggression from yesterday pressure
    pressure_risk = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure_risk = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure_risk = 0.7
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        pressure_risk = 0.4
    else:
        pressure_risk = 0.2

    # If Cindy specifically pressured yesterday, increase slightly.
    if cindy_pressure >= DAILY_SALARY * 0.8:
        pressure_risk = min(1.0, pressure_risk + 0.2)

    # Tight supply => bid more. supply_ratio low => tighter.
    tightness = 1.0 - supply_ratio

    # Compute target bid as a fraction of DAILY_SALARY, then clamp by budget.
    # Not going to max-out; we only need enough to beat likely bids.
    frac = 0.35 + 0.35 * hp_risk + 0.25 * no_water_risk + 0.25 * pressure_risk + 0.25 * tightness
    frac = max(0.25, min(0.95, frac))

    # If my HP is healthy and yesterday pressure was low, stay conservative.
    if my_hp >= 7 and highest_prev_bid < DAILY_SALARY * 0.4:
        frac = min(frac, 0.55)

    bid = DAILY_SALARY * frac

    # If Cindy bid very high yesterday, try to slightly over her while still not maxing.
    if cindy_pressure > 0:
        bid = max(bid, cindy_pressure * 0.98)

    # Final clamp to budget and a reasonable upper bound.
    bid = float(min(my_budget, bid))
    if bid < 0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimum to conserve budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine a baseline or highest previous bid
    # If no previous bids or all were 0, assume a moderate base bid to start
    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # If highest_prev_bid is still 0 (e.g., all opponents bid 0 or no trace), set a default
    if highest_prev_bid == 0:
        highest_prev_bid = DAILY_SALARY * 0.4 # A reasonable starting bid

    # Calculate remaining days
    remaining_days = EPISODE_DAYS - day_context['day']

    # Strategy based on my HP and opponent behavior
    # Critical HP: Bid very high to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Low HP: Bid aggressively
    if my_status['hp'] <= 4:
        # Try to outbid the highest previous bid, or ensure a strong bid
        return min(my_status['budget'], max(highest_prev_bid + 10, DAILY_SALARY * 0.85))

    # React to very high previous bids (likely from Alex)
    if highest_prev_bid >= DAILY_SALARY * 0.80: # e.g., 120 for 150 salary
        # If I have a good HP buffer and it's not endgame, slightly outbid
        if my_status['hp'] > 5 and remaining_days > 2:
             return min(my_status['budget'], highest_prev_bid + 5)
        else: # Lower HP or endgame, be more aggressive
            return min(my_status['budget'], highest_prev_bid + 15)

    # If highest previous bid was moderate, bid slightly above it or a solid amount
    if highest_prev_bid > DAILY_SALARY * 0.40: # e.g., > 60 for 150 salary
        return min(my_status['budget'], max(highest_prev_bid + 2, DAILY_SALARY * 0.6))

    # Default bid: moderate, conserving budget, if no strong threats or low HP
    return min(my_status['budget'], DAILY_SALARY * 0.5)

